package com.way2jobs.scraper;
import com.way2jobs.entity.*; import com.way2jobs.repository.*; import com.way2jobs.scraper.config.ScraperProperties; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*;
@Service @RequiredArgsConstructor public class ScraperLookupService {private final StateRepository states;private final CategoryRepository categories;private final DepartmentRepository departments;private final ScraperProperties props;private Map<String,State> stateCache=Map.of();private Map<String,Category> categoryCache=Map.of();private Map<String,Department> departmentCache=Map.of();public void refreshCaches(){Map<String,State>s=new HashMap<>();states.findAll().forEach(x->s.put(key(x.getName()),x));stateCache=s;Map<String,Category>c=new HashMap<>();categories.findAll().forEach(x->c.put(key(x.getName()),x));categoryCache=c;Map<String,Department>d=new HashMap<>();departments.findAll().forEach(x->{d.put(key(x.getName()),x);d.put(key(x.getShortName()),x);});departmentCache=d;}public Optional<State> resolveState(String n){return Optional.ofNullable(stateCache.get(key(n)));}public Optional<Category> resolveCategory(String n){return Optional.ofNullable(categoryCache.get(key(n)));}public Optional<Department> resolveDepartment(String n){String mapped=props.getDepartmentAliases().getOrDefault(n,n);Department d=departmentCache.get(key(mapped));if(d==null&&!props.getFallbackDepartmentName().isBlank())d=departmentCache.get(key(props.getFallbackDepartmentName()));return Optional.ofNullable(d);}private String key(String s){return s==null?"":s.trim().toLowerCase(Locale.ROOT);}}
